import { logger } from "@/lib/logger";
import { sendAsync } from "@/lib/network/client";

// Streams a receipt generated by the API to the browser. A plain link hits this route (rather
// than fetch + blob) because blob downloads don't work reliably in in-app browsers like WhatsApp's.
// The signed token in the URL is the authorization, so this works with no session cookies when
// WhatsApp opens the link in an external browser. sendAsync falls back to a system token there.

const RECEIPT_TOKEN = /^[0-9a-f]{32}\.\d{1,12}\.[A-Za-z0-9_-]{43}$/;

function failure(message: string, status: number) {
    return new Response(message, {
        status,
        headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" },
    });
}

export async function GET(_request: Request, { params }: { params: Promise<{ token: string }> }) {
    const { token } = await params;

    const expired = "This receipt link has expired or is invalid. Your transaction is not affected.";
    if (!RECEIPT_TOKEN.test(token)) return failure(expired, 404);

    try {
        // Sent as a header because fetchWithToken logs the URL.
        const res = await sendAsync("/receipts", {
            method: "GET",
            headers: { "X-RECEIPT-TOKEN": token },
        });

        if (res.status === 404) return failure(expired, 404);
        if (!res.ok) return failure("Could not download your receipt. Your transaction is not affected.", 502);

        return new Response(res.body, {
            headers: {
                "Content-Type": "application/pdf",
                "Content-Disposition": res.headers.get("Content-Disposition") ?? 'attachment; filename="receipt.pdf"',
                "Cache-Control": "private, no-store",
            },
        });
    } catch (err) {
        logger.error({ err }, "Failed to download receipt");
        return failure("Could not download your receipt. Your transaction is not affected.", 502);
    }
}
